import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/replies-stagers-20261019',engaged=JSON.parse(await fs.readFile(dir+'/engaged-stagers.json'));const selected=[0,3,6,7,16,29,30,31,34,36,38,41,43,49,50,52].map(i=>engaged[i]);const norm=v=>String(v||'').replace(/\D/g,'').slice(-10);const result=[];
for(let i=0;i<selected.length;i+=4){const jobs=await Promise.allSettled(selected.slice(i,i+4).map(async r=>{const c=r.contact,phone='+1'+norm(c.phone);const peers=(await db('market_contacts',{phone:'ilike.*'+norm(c.phone).slice(-4)+'*'})).filter(x=>norm(x.phone)===norm(c.phone));const threads=[];for(const c of peers)threads.push({contact:c,thread:await db('market_touches',{contact_id:'eq.'+c.id,order:'created_at.asc,id.asc',limit:'1000'})});const sms=await db('sms_messages',{or:`(from_number.eq.${phone},to_number.eq.${phone})`,order:'created_at.desc',limit:'20'});const calls=await db('call_recordings',{phone_number:'eq.'+phone,order:'created_at.desc',limit:'10'});return{contact:c,peers:threads,sms,calls};}));for(const j of jobs){if(j.status==='rejected')throw j.reason;result.push(j.value);}}
const{openZohoMailbox}=await import('../lib/partnership-core/zoho.mjs');const mb=await openZohoMailbox('saturn');const mail=[];for(const q of ['sender:oliveandashinteriors.com','to:info@oliveandashinteriors.com'])mail.push({query:q,messages:await mb.request('/accounts/'+mb.accountId+'/messages/search?'+new URLSearchParams({searchKey:q,start:'1',limit:'200',includeto:'true'}))});await fs.writeFile(dir+'/stager-preflight.json',JSON.stringify({at:new Date().toISOString(),rows:result,mail},null,2));console.log(JSON.stringify(result.map(r=>({name:r.contact.name,peers:r.peers.map(p=>({id:p.contact.id,name:p.contact.name,dnc:p.contact.do_not_contact,suppressed:p.contact.cross_channel_suppressed_at})),latestSMS:r.sms.slice(0,3).map(t=>({at:t.created_at,dir:t.direction,body:t.body})),calls:r.calls.map(c=>({at:c.created_at,text:c.transcript||c.summary}))})),null,2));console.log(JSON.stringify({mail}));
